/*
 * kmem.c - Windows kernel driver: maps a user buffer and services
 *          read/write requests for a caller-chosen virtual address range.
 *
 * Build (kernel):
 *   cl /kernel /W4 /WX /GS- /Gz /nodefaultlib /c kmem.c
 *   link /driver /nodefaultlib /entry:DriverEntry /subsystem:native kmem.obj
 *       ntoskrnl.lib
 *
 * Smoke-test build (user-mode, for static analysis only):
 *   cl /DSMOKE_TEST /W3 /nodefaultlib- kmem.c
 */

#include <ntddk.h>
#include <wdm.h>

/* -----------------------------------------------------------------------
 * IOCTL codes
 * ----------------------------------------------------------------------- */
#define KMEM_DEVICE_TYPE    0x8000u

#define IOCTL_KMEM_READ     CTL_CODE(KMEM_DEVICE_TYPE, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_KMEM_CLOSE_VA CTL_CODE(KMEM_DEVICE_TYPE, 0x803, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_KMEM_WRITE    CTL_CODE(KMEM_DEVICE_TYPE, 0x802, METHOD_BUFFERED, FILE_ANY_ACCESS)

/* -----------------------------------------------------------------------
 * Wire structures shared with user mode
 * ----------------------------------------------------------------------- */
#pragma pack(push, 1)

/*
 * KMEM_RW_REQUEST – issued for IOCTL_KMEM_READ and IOCTL_KMEM_WRITE.
 *
 *  TargetAddress  : virtual address in the *calling* process to read from /
 *                   write to.
 *  Length         : number of bytes to transfer.
 *  Buffer         : for READ  – driver fills this with data copied from
 *                               TargetAddress.
 *                   for WRITE – caller fills this with data to be written to
 *                               TargetAddress.
 *
 * The IRP system buffer is sizeof(KMEM_RW_REQUEST) bytes; the inline Buffer
 * field is variable-length and the total SystemBuffer allocation must be:
 *   sizeof(KMEM_RW_REQUEST) - 1 + Length
 */
typedef struct _KMEM_RW_REQUEST {
    ULONG64  TargetAddress;   /* caller VA to read from / write to         */
    ULONG32  Length;          /* bytes; must be > 0 and <= KMEM_MAX_XFER   */
    UCHAR    Buffer[1];       /* in/out payload                            */
} KMEM_RW_REQUEST, *PKMEM_RW_REQUEST;

#pragma pack(pop)

#define KMEM_MAX_XFER        (64u * 1024u * 1024u)   /* 64 MiB hard cap   */
#define KMEM_DEVICE_NAME     L"\\Device\\KMem"
#define KMEM_SYMLINK_NAME    L"\\DosDevices\\KMem"
#define KMEM_TAG             'meMK'

/* -----------------------------------------------------------------------
 * Device extension
 * ----------------------------------------------------------------------- */
typedef struct _KMEM_DEVICE_EXT {
    PDEVICE_OBJECT  DeviceObject;
} KMEM_DEVICE_EXT, *PKMEM_DEVICE_EXT;

/* -----------------------------------------------------------------------
 * Forward declarations
 * ----------------------------------------------------------------------- */
DRIVER_UNLOAD         KmemUnload;
DRIVER_DISPATCH       KmemCreate;
DRIVER_DISPATCH       KmemClose;
DRIVER_DISPATCH       KmemDeviceControl;

static NTSTATUS KmemRead (PIRP Irp, PIO_STACK_LOCATION Stack);
static NTSTATUS KmemWrite(PIRP Irp, PIO_STACK_LOCATION Stack);

/* -----------------------------------------------------------------------
 * DriverEntry
 * ----------------------------------------------------------------------- */
NTSTATUS
DriverEntry(
    _In_ PDRIVER_OBJECT  DriverObject,
    _In_ PUNICODE_STRING RegistryPath)
{
    NTSTATUS         status;
    PDEVICE_OBJECT   devObj  = NULL;
    UNICODE_STRING   devName, symLink;

    UNREFERENCED_PARAMETER(RegistryPath);

    RtlInitUnicodeString(&devName,  KMEM_DEVICE_NAME);
    RtlInitUnicodeString(&symLink,  KMEM_SYMLINK_NAME);

    status = IoCreateDevice(
                 DriverObject,
                 sizeof(KMEM_DEVICE_EXT),
                 &devName,
                 FILE_DEVICE_UNKNOWN,
                 FILE_DEVICE_SECURE_OPEN,
                 FALSE,
                 &devObj);

    if (!NT_SUCCESS(status)) {
        KdPrint(("KMem: IoCreateDevice failed %08X\n", status));
        return status;
    }

    /* Use buffered I/O so the I/O manager allocates and validates the
     * system buffer for every IRP. */
    devObj->Flags |= DO_BUFFERED_IO;

    status = IoCreateSymbolicLink(&symLink, &devName);
    if (!NT_SUCCESS(status)) {
        KdPrint(("KMem: IoCreateSymbolicLink failed %08X\n", status));
        IoDeleteDevice(devObj);
        return status;
    }

    DriverObject->DriverUnload                         = KmemUnload;
    DriverObject->MajorFunction[IRP_MJ_CREATE]         = KmemCreate;
    DriverObject->MajorFunction[IRP_MJ_CLOSE]          = KmemClose;
    DriverObject->MajorFunction[IRP_MJ_DEVICE_CONTROL] = KmemDeviceControl;

    devObj->Flags &= ~DO_DEVICE_INITIALIZING;

    KdPrint(("KMem: driver loaded\n"));
    return STATUS_SUCCESS;
}

/* -----------------------------------------------------------------------
 * KmemUnload
 * ----------------------------------------------------------------------- */
VOID
KmemUnload(_In_ PDRIVER_OBJECT DriverObject)
{
    UNICODE_STRING symLink;
    RtlInitUnicodeString(&symLink, KMEM_SYMLINK_NAME);
    IoDeleteSymbolicLink(&symLink);
    IoDeleteDevice(DriverObject->DeviceObject);
    KdPrint(("KMem: driver unloaded\n"));
}

/* -----------------------------------------------------------------------
 * KmemCreate / KmemClose
 * ----------------------------------------------------------------------- */
NTSTATUS
KmemCreate(
    _In_ PDEVICE_OBJECT DeviceObject,
    _In_ PIRP           Irp)
{
    UNREFERENCED_PARAMETER(DeviceObject);
    Irp->IoStatus.Status      = STATUS_SUCCESS;
    Irp->IoStatus.Information = 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

NTSTATUS
KmemClose(
    _In_ PDEVICE_OBJECT DeviceObject,
    _In_ PIRP           Irp)
{
    UNREFERENCED_PARAMETER(DeviceObject);
    Irp->IoStatus.Status      = STATUS_SUCCESS;
    Irp->IoStatus.Information = 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

/* -----------------------------------------------------------------------
 * KmemDeviceControl – dispatch for all IOCTLs
 * ----------------------------------------------------------------------- */
NTSTATUS
KmemDeviceControl(
    _In_ PDEVICE_OBJECT DeviceObject,
    _In_ PIRP           Irp)
{
    PIO_STACK_LOCATION stack;
    NTSTATUS           status;

    UNREFERENCED_PARAMETER(DeviceObject);

    stack = IoGetCurrentIrpStackLocation(Irp);

    switch (stack->Parameters.DeviceIoControl.IoControlCode) {

    case IOCTL_KMEM_READ:
        status = KmemRead(Irp, stack);
        break;

    case IOCTL_KMEM_WRITE:
        status = KmemWrite(Irp, stack);
        break;

    case IOCTL_KMEM_CLOSE_VA:
        /* Nothing to release on the kernel side for this model; the IOCTL
         * exists so user mode can signal intent without a separate handle. */
        status = STATUS_SUCCESS;
        Irp->IoStatus.Information = 0;
        break;

    default:
        status = STATUS_INVALID_DEVICE_REQUEST;
        Irp->IoStatus.Information = 0;
        break;
    }

    Irp->IoStatus.Status = status;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return status;
}

/* -----------------------------------------------------------------------
 * KmemRead
 *
 * Reads Length bytes from TargetAddress in the calling process and returns
 * them in the same KMEM_RW_REQUEST.Buffer field.
 *
 * The I/O manager already validated that SystemBuffer is at least
 * InputBufferLength bytes; we re-check the arithmetic ourselves.
 * ----------------------------------------------------------------------- */
static NTSTATUS
KmemRead(
    _In_ PIRP               Irp,
    _In_ PIO_STACK_LOCATION Stack)
{
    PKMEM_RW_REQUEST req;
    ULONG            inLen, minLen, xferLen;
    PVOID            targetVa;
    NTSTATUS         status;

    inLen  = Stack->Parameters.DeviceIoControl.InputBufferLength;
    xferLen= 0;

    /* Minimum: fixed header without the flexible Buffer byte. */
    minLen = (ULONG)(FIELD_OFFSET(KMEM_RW_REQUEST, Buffer));

    if (inLen < minLen) {
        return STATUS_BUFFER_TOO_SMALL;
    }

    req = (PKMEM_RW_REQUEST)Irp->AssociatedIrp.SystemBuffer;

    if (req->Length == 0 || req->Length > KMEM_MAX_XFER) {
        return STATUS_INVALID_PARAMETER;
    }

    /* Total buffer must hold the header + Length payload bytes. */
    if (inLen < minLen + req->Length) {
        return STATUS_BUFFER_TOO_SMALL;
    }

    /* Output buffer must be at least as large as input. */
    if (Stack->Parameters.DeviceIoControl.OutputBufferLength < inLen) {
        return STATUS_BUFFER_TOO_SMALL;
    }

    targetVa = (PVOID)(ULONG_PTR)req->TargetAddress;

    __try {
        /* Probe the user VA range for read. This raises an exception if the
         * range is not accessible from user mode. */
        ProbeForRead(targetVa, (SIZE_T)req->Length, 1);

        RtlCopyMemory(req->Buffer, targetVa, (SIZE_T)req->Length);
        xferLen = minLen + req->Length;
        status  = STATUS_SUCCESS;
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        status  = GetExceptionCode();
        xferLen = 0;
        KdPrint(("KMem: read exception %08X at VA %p\n",
                 status, targetVa));
    }

    Irp->IoStatus.Information = (ULONG_PTR)xferLen;
    return status;
}

/* -----------------------------------------------------------------------
 * KmemWrite
 *
 * Writes Length bytes from Buffer in the KMEM_RW_REQUEST into
 * TargetAddress in the calling process.
 * ----------------------------------------------------------------------- */
static NTSTATUS
KmemWrite(
    _In_ PIRP               Irp,
    _In_ PIO_STACK_LOCATION Stack)
{
    PKMEM_RW_REQUEST req;
    ULONG            inLen, minLen;
    PVOID            targetVa;
    NTSTATUS         status;

    inLen   = Stack->Parameters.DeviceIoControl.InputBufferLength;
    minLen  = (ULONG)(FIELD_OFFSET(KMEM_RW_REQUEST, Buffer));

    if (inLen < minLen) {
        return STATUS_BUFFER_TOO_SMALL;
    }

    req = (PKMEM_RW_REQUEST)Irp->AssociatedIrp.SystemBuffer;

    if (req->Length == 0 || req->Length > KMEM_MAX_XFER) {
        return STATUS_INVALID_PARAMETER;
    }

    if (inLen < minLen + req->Length) {
        return STATUS_BUFFER_TOO_SMALL;
    }

    targetVa = (PVOID)(ULONG_PTR)req->TargetAddress;

    __try {
        /* Probe the user VA range for write. */
        ProbeForWrite(targetVa, (SIZE_T)req->Length, 1);

        RtlCopyMemory(targetVa, req->Buffer, (SIZE_T)req->Length);
        status = STATUS_SUCCESS;
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        status = GetExceptionCode();
        KdPrint(("KMem: write exception %08X at VA %p\n",
                 status, targetVa));
    }

    Irp->IoStatus.Information = (NT_SUCCESS(status) ? 0 : 0);
    return status;
}

/* -----------------------------------------------------------------------
 * Smoke-test stub – links as a console application for static analysis.
 * Not executed in a real driver build.
 * ----------------------------------------------------------------------- */
#ifdef SMOKE_TEST
#include <stdio.h>
int main(void)
{
    printf("KMem smoke-test build OK\n");
    printf("  IOCTL_KMEM_READ    = 0x%08X\n", (unsigned)IOCTL_KMEM_READ);
    printf("  IOCTL_KMEM_WRITE   = 0x%08X\n", (unsigned)IOCTL_KMEM_WRITE);
    printf("  IOCTL_KMEM_CLOSE_VA= 0x%08X\n", (unsigned)IOCTL_KMEM_CLOSE_VA);
    printf("  KMEM_MAX_XFER      = %u bytes\n", KMEM_MAX_XFER);
    return 0;
}
#endif /* SMOKE_TEST */
